1	import type { H3Event } from "../event.ts";
2	import { HTTPError } from "../error.ts";
3	import { decodePreservingSeparators, withoutTrailingSlash } from "./internal/path.ts";
4	import { isCanonicalPath } from "./path.ts";
5	import { getType, getExtension } from "./internal/mime.ts";
6	import { isCacheMatch } from "./internal/cache.ts";
7	import { HTTPResponse } from "../response.ts";
8	
9	export interface StaticAssetMeta {
10	  type?: string;
11	  etag?: string;
12	  mtime?: number | string | Date;
13	  size?: number;
14	  encoding?: string;
15	}
16	
17	export interface ServeStaticOptions {
18	  /**
19	   * This function should resolve asset meta.
20	   *
21	   * **Security:** The `id` keeps encoded separators (`%2f`, `%5c`)
22	   * percent-encoded. Decoding them here re-introduces separators and defeats
23	   * the traversal normalization done by `serveStatic`. See {@link serveStatic}.
24	   */
25	  getMeta: (id: string) => StaticAssetMeta | undefined | Promise<StaticAssetMeta | undefined>;
26	
27	  /**
28	   * This function should resolve asset content.
29	   *
30	   * **Security:** As with `getMeta`, the `id` must not be decoded before
31	   * resolving the asset. See {@link serveStatic}.
32	   */
33	  getContents: (id: string) => BodyInit | null | undefined | Promise<BodyInit | null | undefined>;
34	
35	  /**
36	   * Headers to set on the response
37	   */
38	  headers?: HeadersInit;
39	
40	  /**
41	   * Map of supported encodings (compressions) and their file extensions.
42	   *
43	   * Each extension will be appended to the asset path to find the compressed version of the asset.
44	   *
45	   * @example { gzip: ".gz", br: ".br" }
46	   */
47	  encodings?: Record<string, string>;
48	
49	  /**
50	   * Default index file to serve when the path is a directory
51	   *
52	   * @default ["/index.html"]
53	   */
54	  indexNames?: string[];
55	
56	  /**
57	   * When set to true, the function will not throw 404 error when the asset meta is not found or meta validation failed
58	   */
59	  fallthrough?: boolean;
60	
61	  /**
62	   * Custom MIME type resolver function
63	   * @param ext - File extension including dot (e.g., ".css", ".js")
64	   */
65	  getType?: (ext: string) => string | undefined;
66	}
67	
68	/**
69	 * Dynamically serve static assets based on the request path.
70	 *
71	 * **Security — path traversal:** `serveStatic` resolves `.`/`..` segments but
72	 * deliberately keeps encoded separators (`%2f`, `%5c`) percent-encoded in the
73	 * `id` it passes to `getMeta`/`getContents`, exactly as `event.url.pathname`
74	 * does. The `id` therefore has the same segment structure the router and
75	 * pathname-scoped `use()` guards matched on: `/private%5cx` stays one opaque
76	 * segment and cannot be served as `/private/x` past a `use("/private/**")`
77	 * guard. Resolve the `id` against your asset root as an opaque string — a
78	 * backend that decodes it re-introduces separators and re-opens the hole.
79	 *
80	 * A **non-canonical pathname is not served** (404, or falls through when
81	 * `fallthrough` is set): more than one leading separator (`//private/x`,
82	 * `/\\private/x`) or a dot segment that survived URL canonicalization, which
83	 * means one spelled with `%25`-nested escapes (`/pub/%252e%252e/private/x`).
84	 * Both dispatch to a catch-all route while missing a narrower
85	 * `use("/private/**")` guard, and the only `id` `serveStatic` could build from
86	 * them resolves back into the guarded path. Assets are reachable under their
87	 * canonical spelling — the one routing and `use()` guards match on — only.
88	 *
89	 * Everything else is decoded once for the on-disk lookup, so a file's real name
90	 * reaches the backend: `/50%25.png` → `/50%.png`, `/a%20b` → `/a b`, and one
91	 * `%25` level is peeled off a nested separator (`/a%252fb` → `/a%2fb`, still a
92	 * literal `%2f`, never a boundary). RFC 3986's reserved set stays encoded, so an
93	 * `id` can never grow a `?` or `#` that would truncate it in a URL.
94	 *
95	 * Two things `serveStatic` cannot enforce for filesystem-backed assets:
96	 * **case-insensitive filesystems** (macOS, Windows) need both sides of any
97	 * allow/deny check case-folded (otherwise `/SECRET.env` slips past a check for
98	 * `/secret.env`), and **symlinks** need the resolved path re-asserted against
99	 * the asset root after following links (e.g. `realpath(target)`).
100	 */
101	export async function serveStatic(
102	  event: H3Event,
103	  options: ServeStaticOptions,
104	): Promise<HTTPResponse | undefined> {
105	  if (options.headers) {
106	    const entries = Array.isArray(options.headers)
107	      ? options.headers
108	      : typeof options.headers.entries === "function"
109	        ? options.headers.entries()
110	        : Object.entries(options.headers);
111	    for (const [key, value] of entries) {
112	      event.res.headers.set(key, value);
113	    }
114	  }
115	
116	  if (event.req.method !== "GET" && event.req.method !== "HEAD") {
117	    if (options.fallthrough) {
118	      return;
119	    }
120	    event.res.headers.set("allow", "GET, HEAD");
121	    throw new HTTPError({ status: 405 });
122	  }
123	
124	  // The id has to keep the segment structure dispatch matched on, so the one
125	  // thing it must never do is *rewrite* the pathname. `isCanonicalPath` rejects
126	  // exactly the inputs `resolveDotSegments` would rewrite rather than pass
127	  // through — a leading `[/\\]` run, a `\`, and a dot segment at any
128	  // `%25`-nesting depth — and each rewrite re-spells the request into a path the
129	  // router never saw:
130	  //   - `//private/x` misses a `use("/private/**")` guard (a literal
131	  //     `startsWith`, matching rou3) while a catch-all static route still
132	  //     matches; clamping the run to a single `/` for the lookup then serves the
133	  //     guarded asset unauthenticated.
134	  //   - `/pub/%252e%252e/private/x` is four opaque segments to `~findRoute` and
135	  //     to that same guard. Canonicalization decodes `%2e` (so the URL parser
136	  //     resolves `/pub/%2e%2e/private/x` before anything matches on it) but never
137	  //     `%25`, so a `%25`-nested spelling is *meant* to stay opaque; resolving
138	  //     those dots here walks the id back to the guarded `/private/x`.
139	  // Same class of hole as the `%5c` peel below, so same answer: refuse, rather
140	  // than serve a second, cache- and WAF-invisible spelling. Assets stay reachable
141	  // under their canonical spelling — the one the router sees — only.
142	  if (!isCanonicalPath(event.url.pathname)) {
143	    if (options.fallthrough) {
144	      return;
145	    }
146	    throw new HTTPError({ status: 404 });
147	  }
148	
149	  // The path is canonical per the check above, so there is no traversal left to
150	  // resolve — the pathname *is* its own resolved form. All that remains is to
151	  // peel one `%25` level for the on-disk lookup (guarded: malformed `%` falls
152	  // back to the still-encoded pathname).
153	  //
154	  // The peel must never turn an encoded separator into a real one. `decodeURI`
155	  // holds back `%2f` (RFC 3986 reserved) but *not* `%5c`, which it decodes to
156	  // `\` — and `/private%5cx` is one opaque segment to `~findRoute` and to a
157	  // `use("/private/**")` guard, so a backend resolving `\` would read it as the
158	  // guarded `/private/x`. `decodePreservingSeparators` keeps both encoded, so the
159	  // id keeps the segment structure routing matched on.
160	  //
161	  // `nested: false` because this is a single decode: one `%25` level off `%252f`
162	  // leaves a literal `%2f`, not a separator, so filenames containing `%2f` stay
163	  // addressable. `decodeURI` (not `decodeURIComponent`) keeps `%23`/`%3f`
164	  // encoded, so a URL-composing backend cannot grow a truncating `#`/`?`.
165	  //
166	  // Re-checked rather than re-resolved: with no separator introduced there is no
167	  // new segment boundary, so a dot segment the peel reveals (one `%25` level off
168	  // `%252e`) can only be one the pathname already carried at a deeper nesting —
169	  // refused above. Resolving one here is precisely what would re-spell the id.
170	  const resolvedId = withoutTrailingSlash(event.url.pathname);
171	  let originalId = resolvedId;
172	  if (resolvedId.includes("%")) {
173	    try {
174	      const decodedId = decodePreservingSeparators(resolvedId, {
175	        decode: decodeURI,
176	        nested: false,
177	      });
178	      if (isCanonicalPath(decodedId)) {
179	        originalId = withoutTrailingSlash(decodedId);
180	      }
181	    } catch {
182	      // Malformed escape (e.g. a trailing `%`): keep the still-encoded
183	      // `resolvedId` already assigned to `originalId` above.
184	    }
185	  }
186	
187	  const acceptEncodings = parseAcceptEncoding(
188	    event.req.headers.get("accept-encoding") || "",
189	    options.encodings,
190	  );
191	
192	  let id = originalId;
193	  // The asset `id` stands for: the same path without a precompressed
194	  // variant's encoding extension.
195	  let assetId = originalId;
196	  let meta: StaticAssetMeta | undefined;
197	
198	  const _ids = idSearchPaths(originalId, acceptEncodings, options.indexNames || ["/index.html"]);
199	
200	  for (const _id of _ids) {
201	    const _meta = await options.getMeta(_id.id);
202	    if (_meta) {
203	      meta = _meta;
204	      id = _id.id;
205	      assetId = _id.assetId;
206	      break;
207	    }
208	  }
209	
210	  if (!meta) {
211	    if (options.fallthrough) {
212	      return;
213	    }
214	    throw new HTTPError({ statusCode: 404 });
215	  }
216	
217	  // The chosen variant depends on `accept-encoding` whenever encodings are
218	  // configured, including when the unencoded file is served. Set only once an
219	  // asset is found so a fallthrough does not leak it to the next handler.
220	  if (options.encodings && Object.keys(options.encodings).length > 0) {
221	    const vary = event.res.headers.get("vary") || "";
222	    if (!/(?:^|,)\s*(?:\*|accept-encoding)\s*(?:,|$)/i.test(vary)) {
223	      event.res.headers.append("vary", "accept-encoding");
224	    }
225	  }
226	
227	  let mtimeDate: Date | undefined;
228	  if (meta.mtime) {
229	    mtimeDate = new Date(meta.mtime);
230	    // Truncate to whole seconds to match HTTP date precision, so a client
231	    // echoing our `last-modified` in `if-modified-since` still matches.
232	    mtimeDate.setMilliseconds(0);
233	
234	    if (!event.res.headers.get("last-modified")) {
235	      event.res.headers.set("last-modified", mtimeDate.toUTCString());
236	    }
237	  }
238	
239	  if (meta.etag && !event.res.headers.has("etag")) {
240	    event.res.headers.set("etag", meta.etag);
241	  }
242	
243	  if (isCacheMatch(event.req.headers, { etag: meta.etag, lastModified: mtimeDate })) {
244	    return new HTTPResponse(null, {
245	      status: 304,
246	      statusText: "Not Modified",
247	    });
248	  }
249	
250	  if (!event.res.headers.get("content-type")) {
251	    if (meta.type) {
252	      event.res.headers.set("content-type", meta.type);
253	    } else {
254	      // `/app.js.gz` is still `text/javascript`: resolve the requested asset's
255	      // type, not the extension of its precompressed variant.
256	      const ext = getExtension(assetId);
257	      const type = ext ? (options.getType?.(ext) ?? getType(ext)) : undefined;
258	      if (type) {
259	        event.res.headers.set("content-type", type);
260	      }
261	    }
262	  }
263	
264	  if (meta.encoding && !event.res.headers.get("content-encoding")) {
265	    event.res.headers.set("content-encoding", meta.encoding);
266	  }
267	
268	  if (meta.size !== undefined && meta.size > 0 && !event.res.headers.get("content-length")) {
269	    event.res.headers.set("content-length", meta.size + "");
270	  }
271	
272	  if (event.req.method === "HEAD") {
273	    return new HTTPResponse(null, { status: 200 });
274	  }
275	
276	  const contents = await options.getContents(id);
277	  return new HTTPResponse(contents || null, { status: 200 });
278	}
279	
280	// --- Internal Utils ---
281	
282	// `qvalue` grammar (RFC 9110 section 12.4.2).
283	const WEIGHT_RE = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/;
284	
285	/**
286	 * Resolve the configured encoding extensions a request accepts, most preferred first.
287	 *
288	 * Coding names are case-insensitive, `q=0` means "not acceptable", `*` matches
289	 * any coding not listed explicitly and equal weights keep header order, with
290	 * explicitly listed codings ahead of `*` matches (RFC 9110 section 12.5.3).
291	 */
292	function parseAcceptEncoding(header?: string, encodingMap?: Record<string, string>): string[] {
293	  if (!encodingMap || !header) {
294	    return [];
295	  }
296	  const extensions = new Map<string, string>();
297	  for (const [name, ext] of Object.entries(encodingMap)) {
298	    extensions.set(normalizeCoding(name), ext);
299	  }
300	  // Coding -> weight, in header order. The first occurrence of a coding wins.
301	  const weights = new Map<string, number>();
302	  let wildcard: number | undefined;
303	  for (const part of header.split(",")) {
304	    const [rawName = "", ...params] = part.split(";");
305	    const name = normalizeCoding(rawName);
306	    if (name !== "*" && !extensions.has(name)) {
307	      continue;
308	    }
309	    const qParam = params.find((p) => /^\s*q\s*=/i.test(p));
310	    const qValue = qParam?.slice(qParam.indexOf("=") + 1).trim();
311	    // An unparsable weight drops the coding: identity is always a safe fallback,
312	    // while guessing `1` could force a coding the client tried to refuse.
313	    const q = qValue === undefined ? 1 : WEIGHT_RE.test(qValue) ? Number(qValue) : 0;
314	    if (name === "*") {
315	      wildcard ??= q;
316	    } else if (!weights.has(name)) {
317	      weights.set(name, q);
318	    }
319	  }
320	  if (wildcard) {
321	    for (const name of extensions.keys()) {
322	      if (!weights.has(name)) {
323	        weights.set(name, wildcard);
324	      }
325	    }
326	  }
327	  const accepted = [...weights]
328	    .filter(([, q]) => q > 0)
329	    .sort((a, b) => b[1] - a[1])
330	    .map(([name]) => extensions.get(name)!);
331	  return [...new Set(accepted)];
332	}
333	
334	/** Lowercase a coding name and resolve the `x-gzip` / `x-compress` aliases (RFC 9110 section 8.4.1). */
335	function normalizeCoding(name: string): string {
336	  const coding = name.trim().toLowerCase();
337	  return coding === "x-gzip" || coding === "x-compress" ? coding.slice(2) : coding;
338	}
339	
340	function idSearchPaths(id: string, encodings: string[], indexNames: string[]) {
341	  const ids: { id: string; assetId: string }[] = [];
342	
343	  for (const suffix of ["", ...indexNames]) {
344	    const assetId = `${id}${suffix}`;
345	    for (const encoding of [...encodings, ""]) {
346	      ids.push({ id: `${assetId}${encoding}`, assetId });
347	    }
348	  }
349	
350	  return ids;
351	}
